themeScript.system/dark:
(function () {
    try {
      localStorage.setItem('opencode-color-scheme', "system");
      window.dispatchEvent(new StorageEvent('storage', {
        key: 'opencode-color-scheme',
        newValue: "system",
        storageArea: localStorage,
      }));
      var style = document.getElementById('phonecando-theme');
      if (!style) {
        style = document.createElement('style');
        style.id = 'phonecando-theme';
        (document.head || document.documentElement).appendChild(style);
      }
      style.textContent = "html:root{background-color:#0c0b09!important;--v2-background-bg-base:#0c0b09;--v2-background-bg-deep:#0c0b09;--v2-background-bg-layer-01:#12100c;--v2-background-bg-layer-02:#17140f;--v2-background-bg-layer-03:#17140f;--v2-background-bg-layer-04:#17140f;--v2-text-text-base:#f2ecdf;--v2-text-text-muted:#aaa091;--v2-text-text-faint:#968d80;--v2-icon-icon-base:#aaa091;--v2-icon-icon-muted:#968d80;--v2-icon-icon-faint:#897e6f;--v2-border-border-base:rgba(242, 236, 223, 0.11);--v2-border-border-strong:rgba(242, 236, 223, 0.23);--v2-border-border-muted:rgba(242, 236, 223, 0.11);--v2-background-bg-accent:#f02038;--v2-text-text-accent:#f02038;--v2-text-text-accent-hover:#ff4d5e;--v2-icon-icon-accent:#f02038;--v2-icon-icon-accent-hover:#ff4d5e;--v2-border-border-focus:#f02038;}";
